import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Заказы, контракты и общие цели","description":"","frontmatter":{"pageId":"players/procurement","contentRevision":1},"headers":[],"relativePath":"ru/players/procurement.md","filePath":"ru/players/procurement.md"}'),i={name:"ru/players/procurement.md"};function n(s,e,l,p,d,m){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="заказы-контракты-и-общие-цели" tabindex="-1">Заказы, контракты и общие цели <a class="header-anchor" href="#заказы-контракты-и-общие-цели" aria-label="Permalink to &quot;Заказы, контракты и общие цели&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p><strong>Заказ на закупку:</strong> укажи defName, количество и цену за единицу. Сервер резервирует цену × количество; поставщики выполняют части и сразу получают оплату.</p><p><strong>Адресный контракт:</strong> предложение видно выбранному поставщику, который приносит весь запрошенный объём за один раз.</p><p><strong>Общая цель:</strong> участники вносят ресурсы в эскроу до полного набора. Затем награда распределяется пропорционально вкладу; целочисленный остаток разбирается по возрастанию supplierId, после чего применяется комиссия. Отмена возвращает ресурсы участникам и деньги организатору.</p><p>Перед подтверждением проверь остаток и срок: избыточная поставка не делится автоматически.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Только defName и количество: без фильтра качества, материала, прочности и пешек. До 1 000 000 единиц, 720 часов, 1 000 000 000 серебра, 100 поставок; открытых заказов не больше min(20, MaxLotsPerPlayer). Заморозка прошлых поставщиков может остановить завершение цели.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./economy">Кошелёк, почта и рынок</a></li><li><a href="./../admins/administration">Панель и модерация</a></li></ul>',11)])])}const h=a(i,[["render",n]]);export{u as __pageData,h as default};
